/**
 * PROPOSED live-update contract (Socket.IO), for the backend to implement. None of this exists on the server yet: the names and
 * shapes below are what the frontend is written against, and they can be changed in one place (this file and
 * src/constants/socketEvents.ts) once the backend team has agreed them.
 */

/** Client -> server, sent with an acknowledgement callback: "change this task's status and record my work details". */
export type ChangeStatusRequest = {
  /** Generated by the client for each attempt; the server echoes it back in the broadcast so the sender doesn't apply it twice. */
  requestId: string;
  /** The task's numeric id (the `id` of `/items/:id`). */
  itemId: number;
  /** The backend's status value: OPEN, IN_PROGRESS, BLOCKED, ON_HOLD or COMPLETED. */
  status: string;
  /** The required work details / comment. The server should store them in the task's activity with the user and the time. */
  details: string;
};

/** The server's answer to a ChangeStatusRequest, sent only after the change has been validated AND saved. */
export type ChangeStatusAck = { ok: true } | { ok: false; message: string };

/**
 * Server -> every connected client that may see the task, broadcast after a change was saved. Clients re-read the task over REST
 * (`GET /items/:id`) when it arrives, so the payload only has to say what changed; it is not trusted for the task's data.
 */
export type StatusChangedEvent = {
  itemId: number;
  status: string;
  /** The `requestId` of the request that caused it, if any (lets the sender skip its own echo). */
  requestId?: string;
  /** When it was saved (ISO time); with `itemId` it identifies the event, so a repeated delivery is ignored. */
  changedAt?: string;
};
